const responseXML = pm.response.text().replace(/ns\d+:/g, '');
const response = xml2Json(responseXML);

try {
    const cardHandle = response['soap:Envelope']['soap:Body']['GetCardsResponse']['Cards']['Card']['CardHandle'];

    pm.collectionVariables.set('CARD_HANDLE', cardHandle);
} catch (e) {
    console.error(e);
}
